/**
 * Bundled EGM96 geoid undulation grid — the data behind `lib/egm96.ts`.
 *
 * Generated once (throwaway script, not committed) from the `egm96` pip
 * package, which bundles the full 5' EGM96 model. What is stored here:
 *
 * - **Quantity**: EGM96 geoid undulation N — the height of the geoid above
 *   the WGS84 ellipsoid, in **centimetres**, signed int16, row-major.
 * - **Orientation**: row 0 is latitude +90°, row 360 is -90° (step -0.5°);
 *   column 0 is longitude -180°, column 719 is +179.5° (step +0.5°).
 *   Column 720 does not exist: +180° wraps onto column 0, which carries the
 *   same value because the source grid duplicates the seam.
 * - **Sampling**: 361 x 720 = 259,920 nodes on 30' (0.5°) centres, the first
 *   cell centre being (lat +90°, lon -180°). Node values are *decimated*
 *   from the 5' source — each stored node is exactly the EGM96 value at that
 *   node, not an area average — so the grid introduces no smoothing.
 * - **Nodata**: none. EGM96 is defined globally, including over the ocean
 *   and the poles.
 * - **Accuracy**: bilinear interpolation between 30' nodes was measured
 *   against the 5' source over 20,000 random global points: max 1.91 m,
 *   p99 0.53 m, mean 0.07 m (worst case is steep-gradient ocean trench
 *   coastlines). Node-exact, quantisation is 1 cm.
 * - **Encoding**: second differences (longitude diff, then latitude diff,
 *   zero-prepended so the first row/column carry first differences) as int16,
 *   gzip -9, base64. Second differences of a smooth geoid are small and
 *   repetitive, so the payload is 363,592 base64 chars (272,693 gz bytes)
 *   against 693,120 chars for the raw grid — and it decodes synchronously
 *   with two cumulative sums, no DecompressionStream needed.
 *
 * Reference spot values (metres, from the 5' source) live in
 * `src/lib/__tests__/egm96.test.ts`.
 */

/** Rows: latitude +90° (index 0) to -90° (index 360). */
export const EGM96_GRID_ROWS = 361;
/** Columns: longitude -180° (index 0) to +179.5° (index 719); +180° wraps. */
export const EGM96_GRID_COLS = 720;
/** Node spacing in degrees (30 arc-minutes). */
export const EGM96_GRID_STEP_DEG = 0.5;
/** Latitude of row 0, in degrees. */
export const EGM96_GRID_LAT0 = 90;
/** Longitude of column 0, in degrees. */
export const EGM96_GRID_LON0 = -180;

/**
 * gzip'd second differences of the int16 centimetre grid, base64-encoded.
 * Decode with `decodeEgm96Grid()` in `lib/egm96.ts`.
 */
export const EGM96_GRID_PAYLOAD =
  "";
